def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count how often the opponent retaliated to our defections,
    # and how often they forgave (cooperated after our defection).
    retaliation = 0
    forgiveness = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                retaliation += 1
            elif history[i + 1][1] == 'C':
                forgiveness += 1

    last_m, last_o = history[-1]

    # If the opponent has ever retaliated to our defection, play a forgiving TFT.
    if retaliation > 0:
        if last_m == 'D' and last_o == 'D':
            return 'C'
        if last_o == 'D':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
        return 'C'

    # If the opponent has forgiven us multiple times, they are exploitable.
    if forgiveness >= 2:
        return 'D'

    # Otherwise, play basic TFT, but occasionally probe with a defection.
    if last_o == 'D':
        return 'D'
    else:
        # Probe every 10 rounds if the opponent has been cooperative.
        if n > 5 and n % 10 == 0:
            return 'D'
        return 'C'
